import{_ as t,C as n,o as r,c as s,ag as o,E as i}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Manage Profile","description":"","frontmatter":{},"headers":[],"relativePath":"sellers/seller-profile.md","filePath":"sellers/seller-profile.md","lastUpdated":1787558413000}'),l={name:"sellers/seller-profile.md"};function d(h,e,p,g,c,u){const a=n("ImagePopup");return r(),s("div",null,[e[0]||(e[0]=o('<h1 id="manage-profile" tabindex="-1">Manage Profile <a class="header-anchor" href="#manage-profile" aria-label="Permalink to &quot;Manage Profile&quot;">​</a></h1><p>Manage Profile is the seller&#39;s own record of who they are — the shop name, description, policies, address and social links that customers see, plus the logo and banner that brand the store page. It&#39;s also where a seller checks what the admin has granted them.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>Where to find the profile screen</li><li>What you can change, and what is read-only</li><li>Why keeping the profile complete matters</li></ul></div><h2 id="finding-it" tabindex="-1">Finding it <a class="header-anchor" href="#finding-it" aria-label="Permalink to &quot;Finding it&quot;">​</a></h2><p>Open <strong>Manage Profile</strong> from your account menu in the Seller Panel header, or follow the <strong>Complete Your Profile →</strong> link on the <a href="/sellers/seller-dashboard">Dashboard</a>.</p><p>A <strong>channel</strong> and <strong>locale</strong> switcher at the top lets you keep different values per storefront and per language, so a shop selling into two channels can describe itself differently in each.</p>',6)),i(a,{src:"/images/seller-profile/manage-profile.png",alt:"Manage Profile form with the logo and banner section, detail fields and the Shop Information panel"}),e[1]||(e[1]=o('<h2 id="logo-and-banner" tabindex="-1">Logo and banner <a class="header-anchor" href="#logo-and-banner" aria-label="Permalink to &quot;Logo and banner&quot;">​</a></h2><p>Two images brand your storefront:</p><p><strong>Logo:</strong> Upload in a ratio of <strong>1:1</strong>. <strong>Banner:</strong> Upload in a ratio of <strong>3:1</strong>. A resolution of <strong>1320 × 300</strong> is recommended.</p><p>Each has an <strong>Upload New</strong> control and a <strong>Delete</strong> control, so you can replace or clear either one. How large a file you can upload is capped by the admin&#39;s <strong>Max File Upload Size</strong> setting.</p><h2 id="your-details" tabindex="-1">Your details <a class="header-anchor" href="#your-details" aria-label="Permalink to &quot;Your details&quot;">​</a></h2><p>The rest of the form is built from the <a href="/sellers/seller-attributes">seller attributes</a> the admin has marked as visible on the profile, arranged into the groups and columns set on the attribute <strong>Mapping</strong> screen. On a default marketplace that means business details, a shop description, return / shipping / privacy policies, meta description, address, and social links.</p><p>Fill in what applies and select <strong>Save Profile</strong>.</p><h2 id="shop-information" tabindex="-1">Shop Information <a class="header-anchor" href="#shop-information" aria-label="Permalink to &quot;Shop Information&quot;">​</a></h2><p>A read-only panel beside the form shows what the admin has decided for your shop. You can&#39;t change any of it here — it&#39;s shown so you know the terms you&#39;re selling under:</p><ul><li><strong>Admin Commission</strong> — the rate applied to your sales, expressed as a percentage of the total invoiced amount. See <a href="/payments/commission-management">Commission Management</a>.</li><li><strong>Allowed Product Type</strong> — the kinds of product you may list.</li><li><strong>Restricted Categories</strong> — categories you may not sell into.</li><li><strong>Payment Methods</strong> and <strong>Shipping Methods</strong> — what is available on your orders.</li><li><strong>Magic AI</strong> — whether it&#39;s enabled for your shop, and if so your <strong>Generation Limit</strong>, <strong>Limit Period</strong> (<strong>Daily</strong> or <strong>Monthly</strong>), and how much you have <strong>Used In Current Period</strong>. An unlimited quota shows as <strong>Unlimited</strong>. See <a href="/catalog/magic-ai">Magic AI</a>.</li></ul><p>Where a section has nothing in it, the panel says so rather than showing an empty list — for example, no categories or no payment methods available.</p><div class="warning custom-block"><p class="custom-block-title">A complete profile unlocks listing</p><p>The product create flow is only available once your profile is complete. If it isn&#39;t, the <strong>List Your Product</strong> launcher sends you here first. See <a href="/catalog/product-management#adding-a-product">Product Management</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Your profile is what a shopper reads on your <a href="/storefront/seller-storefront">store page</a> before deciding to buy — the description, the policies and the banner do the selling when you aren&#39;t there to do it.</p></div>',13))])}const y=t(l,[["render",d]]);export{f as __pageData,y as default};
